changeSet.sql:
SET @comm_max = 0;
SELECT CONCAT('SELECT GREATEST(0, ', GROUP_CONCAT(CONCAT('COALESCE((SELECT MAX(id) FROM `', table_name, '`), 0)') SEPARATOR ', '), ') INTO @comm_max') INTO @comm_sql FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name IN ('Notification', 'MessageOrRequest', 'GroupMessageOrRequest', 'CreateGroupMessageOrRequest', 'ShareRecordMessageOrRequest', 'Notification_AUD', 'MessageOrRequest_AUD', 'GroupMessageOrRequest_AUD', 'CreateGroupMessageOrRequest_AUD', 'ShareRecordMessageOrRequest_AUD');
PREPARE comm_statement FROM @comm_sql;
EXECUTE comm_statement;
DEALLOCATE PREPARE comm_statement;
SET @comm_high = GREATEST(@comm_max, COALESCE((SELECT MAX(next_val) FROM hibernate_sequences WHERE sequence_name = 'Communication'), 0));
SET @comm_start = (FLOOR(@comm_high / 50) + 2) * 50;
SET @comm_sql = CONCAT('CREATE SEQUENCE communication_seq START WITH ', @comm_start, ' INCREMENT BY 50 NOCACHE');
PREPARE comm_statement FROM @comm_sql;
EXECUTE comm_statement;
DEALLOCATE PREPARE comm_statement;
SET @comm_max = 0;
SELECT CONCAT('SELECT GREATEST(0, ', GROUP_CONCAT(CONCAT('COALESCE((SELECT MAX(id) FROM `', table_name, '`), 0)') SEPARATOR ', '), ') INTO @comm_max') INTO @comm_sql FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name IN ('CommunicationTarget', 'CommunicationTarget_AUD');
PREPARE comm_statement FROM @comm_sql;
EXECUTE comm_statement;
DEALLOCATE PREPARE comm_statement;
SET @comm_high = GREATEST(@comm_max, COALESCE((SELECT MAX(next_val) FROM hibernate_sequences WHERE sequence_name = 'CommunicationTarget'), 0));
SET @comm_start = (FLOOR(@comm_high / 50) + 2) * 50;
SET @comm_sql = CONCAT('CREATE SEQUENCE communication_target_seq START WITH ', @comm_start, ' INCREMENT BY 50 NOCACHE');
PREPARE comm_statement FROM @comm_sql;
EXECUTE comm_statement;
DEALLOCATE PREPARE comm_statement;
